  1→import { useState, useEffect, useCallback } from "react";
  2→import { useNavigate } from "react-router-dom";
  3→import { useAuth } from "@/hooks/useAuth";
  4→import { supabase } from "@/integrations/supabase/client";
  5→import AppHeader from "@/components/AppHeader";
  6→import JobSidebar from "@/components/JobSidebar";
  7→import { SidebarProvider, SidebarTrigger, SidebarInset } from "@/components/ui/sidebar";
  8→import { toast } from "sonner";
  9→
 10→interface PastJob {
 11→  id: string;
 12→  title: string | null;
 13→  job_description: string;
 14→  created_at: string;
 15→  status: string;
 16→  resume_count: number;
 17→  inbox_email: string | null;
 18→}
 19→
 20→/**
 21→ * Shared layout with persistent JobSidebar + AppHeader.
 22→ * Used by all authenticated pages (Settings, Admin, BookDemo, RequestFeature).
 23→ * Selecting a job navigates to "/" where the full dashboard loads.
 24→ */
 25→const SidebarLayout = ({ children }: { children: React.ReactNode }) => {
 26→  const { user } = useAuth();
 27→  const navigate = useNavigate();
 28→  const [pastJobs, setPastJobs] = useState<PastJob[]>([]);
 29→  const [loadingPastJobs, setLoadingPastJobs] = useState(true);
 30→
 31→  const fetchPastJobs = useCallback(async () => {
 32→    if (!user) { setLoadingPastJobs(false); return; }
 33→    try {
 34→      const { data: jobs } = await supabase
 35→        .from("jobs")
 36→        .select("id, title, job_description, created_at, status, inbox_email")
 37→        .eq("user_id", user.id)
 38→        .order("created_at", { ascending: false })
 39→        .limit(50);
 40→
 41→      if (jobs) {
 42→        const jobIds = jobs.map((j) => j.id);
 43→        const { data: counts } = await supabase
 44→          .from("resumes")
 45→          .select("job_id")
 46→          .in("job_id", jobIds);
 47→
 48→        const countMap: Record<string, number> = {};
 49→        counts?.forEach((r) => { countMap[r.job_id] = (countMap[r.job_id] || 0) + 1; });
 50→
 51→        setPastJobs(jobs.map((j) => ({
 52→          ...j,
 53→          resume_count: countMap[j.id] || 0,
 54→          inbox_email: j.inbox_email ?? null,
 55→        })));
 56→      }
 57→    } catch {
 58→      // Silent fail — sidebar is secondary on these pages
 59→    } finally {
 60→      setLoadingPastJobs(false);
 61→    }
 62→  }, [user]);
 63→
 64→  useEffect(() => { fetchPastJobs(); }, [fetchPastJobs]);
 65→
 66→  const handleSelectJob = (jobId: string) => {
 67→    navigate(`/?job=${jobId}`);
 68→  };
 69→
 70→  const handleNewJob = () => {
 71→    navigate("/");
 72→  };
 73→
 74→  const handleRenameJob = async (jobId: string, newTitle: string) => {
 75→    const { error } = await supabase.from("jobs").update({ title: newTitle }).eq("id", jobId);
 76→    if (error) { toast.error("Failed to rename job"); return; }
 77→    setPastJobs((prev) => prev.map((j) => j.id === jobId ? { ...j, title: newTitle } : j));
 78→    toast.success("Job renamed");
 79→  };
 80→
 81→  const handleDeleteJob = async (jobId: string) => {
 82→    const { error } = await supabase.from("jobs").delete().eq("id", jobId);
 83→    if (error) { toast.error("Failed to delete job"); return; }
 84→    setPastJobs((prev) => prev.filter((j) => j.id !== jobId));
 85→    toast.success("Job deleted");
 86→  };
 87→
 88→  return (
 89→    <SidebarProvider className="h-svh overflow-hidden">
 90→      <JobSidebar
 91→        pastJobs={pastJobs}
 92→        selectedJobId={null}
 93→        showDashboard={false}
 94→        loadingPastJobs={loadingPastJobs}
 95→        onSelectJob={handleSelectJob}
 96→        onNewJob={handleNewJob}
 97→        onDashboard={() => navigate("/")}
 98→        onRenameJob={handleRenameJob}
 99→        onDeleteJob={handleDeleteJob}
100→        onAuthRequired={() => navigate("/auth")}
101→        isAuthenticated={!!user}
102→      />
103→      <SidebarInset className="h-svh overflow-y-auto">
104→        <AppHeader onLogoClick={() => navigate("/")} />
105→        <div className="flex items-center h-10 px-4 border-b border-border md:hidden">
106→          <SidebarTrigger />
107→          <span className="ml-2 text-sm font-medium text-muted-foreground">Job History</span>
108→        </div>
109→        {children}
110→      </SidebarInset>
111→    </SidebarProvider>
112→  );
113→};
114→
115→export default SidebarLayout;
