 1→import { useQuery } from "@tanstack/react-query";
 2→import { supabase } from "@/integrations/supabase/client";
 3→
 4→export interface PlatformConfig {
 5→  max_resumes_per_job: number;
 6→  max_file_size_mb: number;
 7→  resume_retention_days: number;
 8→  payg_per_resume_cost: number;
 9→  topup_min_amount: number;
10→  topup_dodo_product_id: string | null;
11→  booking_embed_url: string | null;
12→}
13→
14→const DEFAULTS: PlatformConfig = {
15→  max_resumes_per_job: 10,
16→  max_file_size_mb: 5,
17→  resume_retention_days: 30,
18→  payg_per_resume_cost: 0.07,
19→  topup_min_amount: 1,
20→  topup_dodo_product_id: null,
21→  booking_embed_url: null,
22→};
23→
24→export const usePlatformConfig = () => {
25→  return useQuery({
26→    queryKey: ["platform_config"],
27→    queryFn: async (): Promise<PlatformConfig> => {
28→      const { data, error } = await supabase.rpc("get_public_platform_config");
29→      if (error || !data) return DEFAULTS;
30→      // RPC RETURNS TABLE gives an array; pick first row
31→      const row = Array.isArray(data) ? data[0] : data;
32→      if (!row) return DEFAULTS;
33→      return { ...DEFAULTS, ...row };
34→    },
35→    retry: false,
36→    placeholderData: DEFAULTS,
37→  });
38→};
