 14→function getInitials(email?: string | null): string {
 15→  if (!email) return "?";
 16→  const name = email.split("@")[0];
 17→  const parts = name.split(/[._-]/);
 18→  if (parts.length >= 2) return (parts[0][0] + parts[1][0]).toUpperCase();
 19→  return name[0]?.toUpperCase() || "?";
 20→}
